# sync-adapters.ps1
# Generate tool-specific files from the single source of truth:
#   agents/roles/*.md  ->  .kilo/agents/<name>.md      (Kilo Code custom agents)
#                      ->  .agents/rules/role-<name>.md (Antigravity rules)
#   AGENTS.md          ->  GEMINI.md, .agents/rules/agents-core.md
#
# Usage:
#   powershell -File scripts/sync-adapters.ps1          write generated files
#   powershell -File scripts/sync-adapters.ps1 -Check   report drift, exit 1 if any
#
# Keep this file ASCII only (Windows PowerShell 5.1 reads BOM-less scripts as ANSI).

param([switch]$Check)

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)
$marker = 'GENERATED by scripts/sync-adapters.ps1'
$antigravityLimit = 12000

function Read-Text([string]$p) { [System.IO.File]::ReadAllText($p, $utf8) }
function Norm([string]$t) { $t -replace "`r`n", "`n" }

function Split-FrontMatter([string]$text) {
  $t = Norm $text
  $m = [regex]::Match($t, '(?s)^---\n(.*?)\n---\n(.*)$')
  if (-not $m.Success) { throw 'missing front matter' }
  return @{ Front = $m.Groups[1].Value; Body = $m.Groups[2].Value }
}

function Parse-Meta([string]$front) {
  $meta = @{}
  $cur = $null
  foreach ($line in ($front -split "`n")) {
    if ($line -match '^\s+-\s+(.+)$') {
      if ($cur) { $meta[$cur] += @($matches[1].Trim().Trim('"')) }
      continue
    }
    if ($line -match '^([a-z_]+):\s*(.*)$') {
      $cur = $matches[1]
      $val = $matches[2].Trim()
      if ($val -eq '') { $meta[$cur] = @() } else { $meta[$cur] = $val }
    }
  }
  return $meta
}

function Get-List($meta, [string]$key) {
  $list = @()
  if ($meta.ContainsKey($key)) { $list = @($meta[$key]) }
  return , $list
}

function Build-Kilo($meta, [string]$body, [string]$srcRel) {
  $allow = Get-List $meta 'edit_allow'
  $deny = Get-List $meta 'edit_deny'
  $desc = ([string]$meta['description']).Replace('"', '\"')
  $sb = New-Object System.Text.StringBuilder
  [void]$sb.Append("---`n")
  [void]$sb.Append("description: `"$desc`"`n")
  [void]$sb.Append("mode: $($meta['mode'])`n")
  [void]$sb.Append("permission:`n")
  if ($allow.Count -eq 0) {
    [void]$sb.Append("  edit: deny`n")
  } else {
    [void]$sb.Append("  edit:`n")
    if ($allow -notcontains '*') { [void]$sb.Append("    `"*`": deny`n") }
    foreach ($a in $allow) { [void]$sb.Append("    `"$a`": allow`n") }
    foreach ($d in $deny) { [void]$sb.Append("    `"$d`": deny`n") }
  }
  switch ($meta['bash']) {
    'none' { [void]$sb.Append("  bash: deny`n") }
    'readonly' {
      [void]$sb.Append("  bash:`n")
      [void]$sb.Append("    `"*`": deny`n")
      foreach ($c in 'git status*', 'git diff*', 'git log*', 'git show*') { [void]$sb.Append("    `"$c`": allow`n") }
    }
    'full' { [void]$sb.Append("  bash: allow`n") }
    default { throw "role $srcRel has invalid bash value: $($meta['bash']) (use none, readonly or full)" }
  }
  [void]$sb.Append("---`n")
  [void]$sb.Append("<!-- $marker from $srcRel. Do not edit. -->`n")
  [void]$sb.Append($body)
  return $sb.ToString()
}

$outputs = [ordered]@{}

$rolesDir = Join-Path $root 'agents/roles'
foreach ($f in (Get-ChildItem $rolesDir -Filter *.md -File | Sort-Object Name)) {
  $srcRel = "agents/roles/$($f.Name)"
  $parts = Split-FrontMatter (Read-Text $f.FullName)
  $meta = Parse-Meta $parts.Front
  foreach ($k in 'name', 'description', 'mode', 'bash') {
    if (-not $meta.ContainsKey($k) -or [string]::IsNullOrWhiteSpace([string]$meta[$k])) { throw "role $srcRel is missing '$k'" }
  }
  if ($meta['name'] -ne $f.BaseName) { throw "role ${srcRel}: name '$($meta['name'])' does not match file name" }
  $outputs[".kilo/agents/$($meta['name']).md"] = Build-Kilo $meta $parts.Body $srcRel
  $outputs[".agents/rules/role-$($meta['name']).md"] = "<!-- $marker from $srcRel. Do not edit. -->`n" + $parts.Body
}

$agentsMd = Norm (Read-Text (Join-Path $root 'AGENTS.md'))
$outputs['GEMINI.md'] = "<!-- $marker from AGENTS.md. Do not edit. -->`n" + $agentsMd
$outputs['.agents/rules/agents-core.md'] = "<!-- $marker from AGENTS.md. Do not edit. -->`n" + $agentsMd

$problems = 0
foreach ($rel in $outputs.Keys) {
  $full = Join-Path $root $rel
  $new = Norm $outputs[$rel]
  if ($rel -like '.agents/rules/*' -and $new.Length -gt $antigravityLimit) {
    Write-Warning "$rel is $($new.Length) chars, over the Antigravity rule limit of $antigravityLimit"
    $problems++
  }
  if ($Check) {
    if (-not (Test-Path $full)) { Write-Host "MISSING  $rel"; $problems++ }
    elseif ((Norm (Read-Text $full)) -ne $new) { Write-Host "OUTDATED $rel"; $problems++ }
  } else {
    $dir = Split-Path $full -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force $dir | Out-Null }
    [System.IO.File]::WriteAllText($full, $new, $utf8)
    Write-Host "wrote    $rel"
  }
}

foreach ($dirRel in '.kilo/agents', '.agents/rules') {
  $dirFull = Join-Path $root $dirRel
  if (-not (Test-Path $dirFull)) { continue }
  foreach ($f in (Get-ChildItem $dirFull -Filter *.md -File)) {
    $rel = "$dirRel/$($f.Name)"
    if ($outputs.Contains($rel)) { continue }
    if ((Read-Text $f.FullName).Contains($marker)) {
      if ($Check) { Write-Host "STALE    $rel"; $problems++ }
      else { Remove-Item $f.FullName; Write-Host "removed  $rel" }
    }
  }
}

if ($Check) {
  if ($problems -gt 0) { Write-Host "FAIL: $problems problem(s). Run scripts/sync-adapters.ps1 to regenerate."; exit 1 }
  Write-Host 'OK: generated files are up to date.'
}
if (-not $Check -and $problems -gt 0) { exit 1 }
exit 0
